    def __init__(self):
        self.teams = {}
        self.games = []
        self.next_game_id = 1

    def add_team(self, name: str) -> None:
        if not name or name in self.teams:
            raise ValueError(f"Invalid team name: {name}")
        self.teams[name] = {
            'wins': 0,
            'losses': 0,
            'ties': 0,
            'points_for': 0,
            'points_against': 0
        }

    def record_game(self, home: str, away: str, home_score: int, away_score: int) -> int:
        if home not in self.teams or away not in self.teams:
            raise KeyError(f"Invalid team: {home} or {away}")
        if home == away:
            raise ValueError("Home and away teams cannot be the same")
        if not isinstance(home_score, int) or not isinstance(away_score, int) or home_score < 0 or away_score < 0:
            raise ValueError("Scores must be non-negative integers")

        game_id = self.next_game_id
        self.next_game_id += 1
        self.games.append((game_id, home, away, home_score, away_score))

        if home_score > away_score:
            self.teams[home]['wins'] += 1
            self.teams[away]['losses'] += 1
        elif home_score < away_score:
            self.teams[away]['wins'] += 1
            self.teams[home]['losses'] += 1
        else:
            self.teams[home]['ties'] += 1
            self.teams[away]['ties'] += 1

        self.teams[home]['points_for'] += home_score
        self.teams[home]['points_against'] += away_score
        self.teams[away]['points_for'] += away_score
        self.teams[away]['points_against'] += home_score

        return game_id

    def get_record(self, team: str) -> dict:
        if team not in self.teams:
            raise KeyError(f"Team not found: {team}")
        return self.teams[team]

    def get_standings(self) -> list[str]:
        return sorted(
            self.teams.keys(),
            key=lambda t: (
                2 * self.teams[t]['wins'] + self.teams[t]['ties'],
                self.teams[t]['points_for'] - self.teams[t]['points_against'],
                -self.teams[t]['points_against'],
                -self.teams[t]['points_for'],
                -self.teams[t]['losses'],
                -self.teams[t]['ties']
            ),
            reverse=True
        )
